begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated;
select no_plan();
-- Actor/organization fixtures are local SQL contracts, not native JWT proofs.
-- Benefit states below are advanced exclusively by the public commands.
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select('a2480000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','benefit248-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,5)i;
insert into public.platform_user_roles(user_id,role_code)values('a2480000-0000-4000-8000-000000000001','SUPER_ADMIN'),('a2480000-0000-4000-8000-000000000002','MATRICIA_ADMIN'),('a2480000-0000-4000-8000-000000000002','FINANCE_MANAGER');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2480000-0000-4000-8000-000000000001','Benefit A TEST','Benefit A TEST','ACTIVE','a2480000-0000-4000-8000-000000000003'),('b2480000-0000-4000-8000-000000000002','Benefit B TEST','Benefit B TEST','ACTIVE','a2480000-0000-4000-8000-000000000005');
insert into public.organization_memberships(id,organization_id,user_id,status)values
 ('c2480000-0000-4000-8000-000000000001','b2480000-0000-4000-8000-000000000001','a2480000-0000-4000-8000-000000000001','ACTIVE'),
 ('c2480000-0000-4000-8000-000000000003','b2480000-0000-4000-8000-000000000001','a2480000-0000-4000-8000-000000000003','ACTIVE'),
 ('c2480000-0000-4000-8000-000000000005','b2480000-0000-4000-8000-000000000002','a2480000-0000-4000-8000-000000000005','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c2480000-0000-4000-8000-000000000001','CLIENT_ADMIN'),('c2480000-0000-4000-8000-000000000003','CLIENT_OWNER'),('c2480000-0000-4000-8000-000000000005','CLIENT_OWNER');
create temporary table benefit248(k text primary key,v jsonb)on commit drop;
grant all on benefit248 to authenticated;
create function pg_temp.benefit_actor(i integer,level text default'aal2')returns void language plpgsql as $$begin
 perform set_config('request.jwt.claim.sub','a2480000-0000-4000-8000-'||lpad(i::text,12,'0'),true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','a2480000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated','aal',level)::text,true);
end$$;
create function pg_temp.benefit_id()returns uuid language sql as $$select(v->>'redemption_id')::uuid from benefit248 where k='reserve'$$;
create function pg_temp.benefit_version()returns bigint language sql as $$select row_version from public.benefit_redemptions where id=pg_temp.benefit_id()$$;
set local role authenticated;select pg_temp.benefit_actor(1);
insert into benefit248 values('benefit',public.create_benefit_version('b2480000-0000-4000-8000-000000000001','TEST_BENEFIT_248','CONSULTATION','MATRICIA_INTERNAL','Consultation TEST','استشارة اختبار','Prestation de recette uniquement','خدمة اختبار فقط',5,1000,0,'MAD',null,null,null,'{}','{}','TEST_CANCELLATION_248',clock_timestamp()-interval'1 minute','benefit248-create'));
select pg_temp.benefit_actor(2);
select public.activate_benefit_version('b2480000-0000-4000-8000-000000000001',(select(v->>'benefit_version_id')::uuid from benefit248 where k='benefit'),'benefit248-activate');
select pg_temp.benefit_actor(1);
insert into benefit248 values('policy-context',public.get_admin_benefit_admission_context_v1((select(v->>'benefit_version_id')::uuid from benefit248 where k='benefit'),1));
insert into benefit248 values('policy',public.propose_benefit_admission_policy_v1((select(v->>'benefit_version_id')::uuid from benefit248 where k='benefit'),(select v->>'source_hash'from benefit248 where k='policy-context'),null,'NONE',null,null,'{}','{}',clock_timestamp()-interval'1 minute',null,'TEST explicit human execution and receipt evidence only','TEST_POLICY_248','HUMAN_OPERATOR_REPORT_AND_INDEPENDENT_CLIENT_RECEIPT_V1','d2480000-0000-4000-8000-000000000001'));
select pg_temp.benefit_actor(2);
select public.decide_benefit_admission_policy_v1((select(v->>'policy_id')::uuid from benefit248 where k='policy'),(select v->>'content_hash'from benefit248 where k='policy'),true,'TEST_POLICY_REVIEW_248','TEST independent approval of the exact human receipt policy');
select pg_temp.benefit_actor(3);
insert into benefit248 values('wallet',public.ensure_client_credit_wallet('b2480000-0000-4000-8000-000000000001','benefit248-wallet'));
select pg_temp.benefit_actor(1);
insert into benefit248 values('gift-request',public.request_manual_credit_grant_v1('b2480000-0000-4000-8000-000000000001',(select(v->>'wallet_id')::uuid from benefit248 where k='wallet'),'ADMIN_GRANT',20,clock_timestamp()+interval'30 days',null,'TEST_MANUAL_BENEFIT_248','TEST real governed manual credit funding for this fixture','benefit248-gift-request'));
select pg_temp.benefit_actor(2);
insert into benefit248 values('gift-review',public.review_manual_credit_grant_v1((select(v->>'request_id')::uuid from benefit248 where k='gift-request'),(select v->>'content_hash'from benefit248 where k='gift-request'),true,true,'TEST_MANUAL_AUTHORIZATION_248','TEST independent review of the exact gift terms'));
select pg_temp.benefit_actor(1);
select public.execute_manual_credit_grant_v1((select(v->>'request_id')::uuid from benefit248 where k='gift-request'),(select v->>'content_hash'from benefit248 where k='gift-request'),(select v->>'review_proof_hash'from benefit248 where k='gift-review'),'benefit248-gift-execute');
select pg_temp.benefit_actor(3);
insert into benefit248 values('reserve',public.reserve_benefit_credits('b2480000-0000-4000-8000-000000000001',(select(v->>'wallet_id')::uuid from benefit248 where k='wallet'),(select(v->>'benefit_version_id')::uuid from benefit248 where k='benefit'),1,clock_timestamp()+interval'7 days','benefit248-reserve'));
select is((select status from public.benefit_redemptions where id=pg_temp.benefit_id()),'RESERVED','the public reservation is real');
select throws_ok($$select public.advance_benefit_fulfillment_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'START',null,'Unauthorized client operation','benefit248-client-deny')$$,'42501','BENEFIT_OPERATIONS_MFA_REQUIRED','client cannot pretend to be the operational fulfiller');
select pg_temp.benefit_actor(1,'aal1');
select throws_ok($$select public.advance_benefit_fulfillment_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'START',null,'Weak operator is refused','benefit248-aal1-deny')$$,'42501','BENEFIT_OPERATIONS_MFA_REQUIRED','operational mutations require MFA');
select pg_temp.benefit_actor(1);
select throws_ok($$select public.advance_benefit_fulfillment_v1(pg_temp.benefit_id(),0,'SCHEDULE',clock_timestamp(),'Stale schedule refused','benefit248-stale')$$,'40001','STALE_BENEFIT_REDEMPTION','schedule binds the exact current version');
select throws_ok($$select public.advance_benefit_fulfillment_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'START',null,'No schedule is not executable','benefit248-order')$$,'55000','BENEFIT_NOT_READY_TO_START','the start cannot skip scheduling');
select throws_ok($$select public.advance_benefit_fulfillment_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'SCHEDULE',clock_timestamp()+interval'8 days','Beyond reserved duration','benefit248-deadline')$$,'55000','INVALID_BENEFIT_SCHEDULE','schedule cannot exceed the actual reservation');
select public.advance_benefit_fulfillment_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'SCHEDULE',clock_timestamp()-interval'1 second','Execution scheduled during the test','benefit248-schedule');
select is((select status from public.benefit_redemptions where id=pg_temp.benefit_id()),'SCHEDULED','the service is actually scheduled');
select public.advance_benefit_fulfillment_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'START',null,'Execution actually started by operator','benefit248-start');
select is((select status from public.benefit_redemptions where id=pg_temp.benefit_id()),'IN_PROGRESS','the service is actually started');
insert into benefit248 values('proposal',public.propose_benefit_delivery_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'Compte rendu de la consultation effectivement réalisée pour cette recette','TEST_SERVICE_ATTENDANCE_248',clock_timestamp(),'benefit248-proposal'));
select is((select status from public.benefit_redemptions where id=pg_temp.benefit_id()),'IN_PROGRESS','a report does not declare the benefit delivered');
select is((select delivery_proof_hash from public.benefit_redemptions where id=pg_temp.benefit_id()),null::text,'a report alone cannot manufacture an accepted delivery proof');
select throws_ok($$select public.decide_my_benefit_delivery_v1((select(v->>'proposal_id')::uuid from benefit248 where k='proposal'),(select v->>'source_hash'from benefit248 where k='proposal'),pg_temp.benefit_version(),true,'The operator cannot approve their own delivery','benefit248-self')$$,'42501','BENEFIT_INDEPENDENT_CLIENT_RECEIPT_REQUIRED','a dual-role operator cannot approve their own report');
select pg_temp.benefit_actor(5);
select throws_ok($$select public.decide_my_benefit_delivery_v1((select(v->>'proposal_id')::uuid from benefit248 where k='proposal'),(select v->>'source_hash'from benefit248 where k='proposal'),1,true,'Foreign client cannot receive this report','benefit248-foreign')$$,'42501','BENEFIT_INDEPENDENT_CLIENT_RECEIPT_REQUIRED','a foreign organization cannot confirm receipt');
select is((select count(*)from public.benefit_delivery_proposals_v1 where redemption_id=pg_temp.benefit_id()),0::bigint,'RLS hides the foreign report');
select throws_ok($$select public.list_benefit_fulfillment_v1('b2480000-0000-4000-8000-000000000001',1)$$,'42501','BENEFIT_FULFILLMENT_DENIED','the listing does not bypass tenant scope');
select pg_temp.benefit_actor(3,'aal1');
select throws_ok($$select public.decide_my_benefit_delivery_v1((select(v->>'proposal_id')::uuid from benefit248 where k='proposal'),(select v->>'source_hash'from benefit248 where k='proposal'),pg_temp.benefit_version(),true,'A fresh AAL1 client still needs MFA','benefit248-client-aal1')$$,'42501','BENEFIT_INDEPENDENT_CLIENT_RECEIPT_REQUIRED','receipt requires client MFA');
select pg_temp.benefit_actor(3);
select throws_ok($$select public.decide_my_benefit_delivery_v1((select(v->>'proposal_id')::uuid from benefit248 where k='proposal'),repeat('0',64),pg_temp.benefit_version(),true,'Changed report hash is not acceptable','benefit248-hash')$$,'40001','STALE_BENEFIT_DELIVERY_PROPOSAL','receipt binds the immutable report hash');
insert into benefit248 values('reject',public.decide_my_benefit_delivery_v1((select(v->>'proposal_id')::uuid from benefit248 where k='proposal'),(select v->>'source_hash'from benefit248 where k='proposal'),pg_temp.benefit_version(),false,'La prestation requiert encore un complément réel','benefit248-reject'));
select is((select status from public.benefit_redemptions where id=pg_temp.benefit_id()),'IN_PROGRESS','rejection leaves the unfinished service in progress');
select pg_temp.benefit_actor(2);
insert into benefit248 values('proposal2',public.propose_benefit_delivery_v1(pg_temp.benefit_id(),pg_temp.benefit_version(),'Complément de consultation remis puis vérifié par le client de cette recette','TEST_SERVICE_ATTENDANCE_248_CORRECTED',null,'benefit248-proposal2'));
select is(public.propose_benefit_delivery_v1(pg_temp.benefit_id(),(select(v->>'row_version')::bigint-1 from benefit248 where k='proposal2'),'Complément de consultation remis puis vérifié par le client de cette recette','TEST_SERVICE_ATTENDANCE_248_CORRECTED',null,'benefit248-proposal2'),(select v from benefit248 where k='proposal2'),'report retries retain the first server-recorded completion time');
select pg_temp.benefit_actor(3);
insert into benefit248 values('accept',public.decide_my_benefit_delivery_v1((select(v->>'proposal_id')::uuid from benefit248 where k='proposal2'),(select v->>'source_hash'from benefit248 where k='proposal2'),(select(v->>'row_version')::bigint from benefit248 where k='proposal2'),true,'Je confirme la réception de la prestation réellement effectuée','benefit248-accept'));
select is(public.decide_my_benefit_delivery_v1((select(v->>'proposal_id')::uuid from benefit248 where k='proposal2'),(select v->>'source_hash'from benefit248 where k='proposal2'),(select(v->>'row_version')::bigint from benefit248 where k='proposal2'),true,'Je confirme la réception de la prestation réellement effectuée','benefit248-accept'),(select v from benefit248 where k='accept'),'authorized receipt replay returns the same immutable receipt');
select is((select status from public.benefit_redemptions where id=pg_temp.benefit_id()),'DELIVERED','independent client receipt actually marks delivery');
select is((select delivery_proof_hash from public.benefit_redemptions where id=pg_temp.benefit_id()),(select v->>'receipt_hash'from benefit248 where k='accept'),'the delivery proof is the canonical accepted receipt hash');
select is((select count(*)from public.credit_lot_movements where redemption_id=pg_temp.benefit_id()and movement_type='CONSUME'),0::bigint,'receipt alone does not consume credits');
select throws_ok($$select public.consume_benefit_credits(pg_temp.benefit_id(),repeat('a',64),'benefit248-wrong-proof')$$,'55000','BENEFIT_ACCEPTED_DELIVERY_PROOF_REQUIRED','a fabricated hash cannot consume an actually delivered benefit');
insert into benefit248 values('consume',public.consume_benefit_credits(pg_temp.benefit_id(),(select v->>'receipt_hash'from benefit248 where k='accept'),'benefit248-consume'));
select is((select status from public.benefit_redemptions where id=pg_temp.benefit_id()),'CONSUMED','the native accepted receipt completes the public consumption command');
select is(public.consume_benefit_credits(pg_temp.benefit_id(),(select v->>'receipt_hash'from benefit248 where k='accept'),'benefit248-consume'),(select v from benefit248 where k='consume'),'consumption replay does not duplicate credit effects');
select is((select count(*)from public.credit_lot_movements where redemption_id=pg_temp.benefit_id()and movement_type='CONSUME'),1::bigint,'one actual consumption movement is appended');
reset role;
select is(private.benefit_admitted_fulfillment_evidence_v1(pg_temp.benefit_id()),'HUMAN_OPERATOR_REPORT_AND_INDEPENDENT_CLIENT_RECEIPT_V1','execution is bound to the independently approved immutable admission');
select ok(not has_function_privilege('authenticated','private.benefit_admitted_fulfillment_evidence_v1(uuid)','EXECUTE'),'the execution policy evidence helper is not callable from the browser');
select is((private.benefit_accepted_receipt_v1(pg_temp.benefit_id(),(select v->>'receipt_hash'from benefit248 where k='accept'))->>'evidence_kind'),'OPERATIONAL_REPORT_WITH_INDEPENDENT_CLIENT_RECEIPT','the private accounting source truthfully identifies a manual client-received report');
select is(private.benefit_accepted_receipt_v1(pg_temp.benefit_id(),repeat('0',64)),null::jsonb,'an arbitrary hash does not become a canonical receipt');
select ok(not has_function_privilege('authenticated','private.benefit_accepted_receipt_v1(uuid,text)','EXECUTE'),'the receipt accounting helper is not an API shortcut');
select is((select count(*)from public.benefit_client_receipts_v1 where redemption_id=pg_temp.benefit_id()and accepted),1::bigint,'exactly one acceptance is stored');
select is((select count(*)from public.event_outbox where aggregate_id=pg_temp.benefit_id()::text and event_type='BenefitDeliveryAcceptedV1'),1::bigint,'the receipt retry emits only one acceptance fact');
select is((select count(*)from public.audit_events where resource_id=pg_temp.benefit_id()::text and action='BenefitDeliveryAcceptedV1'),1::bigint,'the real acceptance is audited once');
select ok(not has_table_privilege('authenticated','public.benefit_client_receipts_v1','INSERT'),'clients cannot forge an acceptance row');
select ok(not has_function_privilege('authenticated','private.record_benefit_fulfillment_fact_v1(uuid,uuid,text,jsonb,text)','EXECUTE'),'browser cannot fabricate fulfillment audit/outbox events');
select throws_ok($$update public.benefit_redemptions set delivery_proof_hash=repeat('f',64)where id=pg_temp.benefit_id()$$,'55000','BENEFIT_NATIVE_CLIENT_RECEIPT_REQUIRED','even privileged accidental rewriting cannot substitute an unrelated proof');
select*from finish();
rollback;
